import fs from 'node:fs'; import crypto from 'node:crypto'; import {execFileSync} from 'node:child_process'; import assert from 'node:assert/strict';
import {keccak256, encodeDeployData, decodeAbiParameters, encodeAbiParameters} from 'viem';
const dir='evidence/HO-hsk-mainnet-1/'; const ext='/workspace/web3-bounty/v3-reconcile/evidence/hsk-mainnet-20261027/';
const load=p=>JSON.parse(fs.readFileSync(p,'utf8')); const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const sourceSha='1f1a48d56df96fc6f838d0696f1b5e3500bcf004';
const artifactBytes=fs.readFileSync('contracts/out/TradingSessionGuard.sol/TradingSessionGuard.json'); const artifact=JSON.parse(artifactBytes);
const manifest=load(ext+'guard-artifact-hashes-20261027.json'), preview=load(ext+'deploy-preview-unsigned-20261027.json');
assert.equal(sha(artifactBytes),manifest.artifactSha256); assert.equal(keccak256(artifact.bytecode.object),manifest.creationBytecodeKeccak256); assert.equal(keccak256(artifact.deployedBytecode.object),manifest.deployedBytecodeKeccak256);
const sourceChecks=[];
for(const [file,source] of Object.entries(artifact.metadata.sources)) { const path=file.startsWith('/')?file:'contracts/'+file; const hash=keccak256(fs.readFileSync(path)); assert.equal(hash,source.keccak256,path); sourceChecks.push({path,keccak256:hash}); }
const frozenFiles=[];
for(const path of ['contracts/src/TradingSessionGuard.sol','contracts/foundry.toml','pnpm-lock.yaml','package.json']) { const fixed=execFileSync('git',['show',sourceSha+':'+path]); const current=fs.readFileSync(path); assert.deepEqual(current,fixed,path); frozenFiles.push({path,sha256:sha(current),matchesFixedSource:true}); }
const p=preview.constructorPreview; const args=[p.initialOwner,p.risk,p.quote,p.fixedRouter,p.fixedFactory,p.fixedPool,p.fee];
const data=encodeDeployData({abi:artifact.abi,bytecode:artifact.bytecode.object,args}); assert.equal(keccak256(data),preview.deployDataKeccak256); assert.equal((data.length-2)/2,preview.deployDataBytes);
const types=artifact.abi.find(x=>x.type==='constructor').inputs; const encoded=encodeAbiParameters(types,args); assert.equal(encoded,preview.constructorArgsAbiEncoded); const decoded=decodeAbiParameters(types,encoded); assert.deepEqual(decoded.map(String).map(x=>x.toLowerCase()),args.map(String).map(x=>x.toLowerCase()));
const report={schemaVersion:'hsk-paused-provenance/1',observedAt:new Date().toISOString(),sourceSha,status:'PASS_ARTIFACT_AND_CONSTRUCTOR_PROVENANCE_NOT_DEPLOYMENT_APPROVAL',artifactPath:manifest.artifactPath,artifactSha256:sha(artifactBytes),compiler:artifact.metadata.compiler,settings:artifact.metadata.settings,sourceChecks,frozenFiles,creationBytecodeKeccak256:keccak256(artifact.bytecode.object),runtimeTemplateKeccak256:keccak256(artifact.deployedBytecode.object),initcodePath:dir+'initcode.hex',initcodeKeccak256:keccak256(data),initcodeBytes:(data.length-2)/2,constructorArgsAbiEncoded:encoded,decodedConstructor:decoded.map(String),immutableReferences:artifact.deployedBytecode.immutableReferences,buildRunExitCode:'UNKNOWN_HISTORICAL_BUILD_LOG_NOT_PRESENT',limitations:['Reused artifact verified against every compiler-metadata source and fixed tracked inputs; no new compilation claimed.','Runtime template requires immutable patching including EIP712 chain/address context; not final mainnet code.','Owner TEST remains proposed; deployer authorization does not prove owner authorization.']};
fs.writeFileSync(dir+'initcode.hex',data+'\n'); fs.writeFileSync(dir+'provenance.json',JSON.stringify(report,null,2)+'\n');
for(const file of ['preflight-177-20261027.json','guard-artifact-hashes-20261027.json','deploy-preview-unsigned-20261027.json']) fs.copyFileSync(ext+file,dir+file);
console.log(JSON.stringify({status:report.status,metadataSourceCount:sourceChecks.length,frozenFiles,initcodeKeccak256:report.initcodeKeccak256,initcodeBytes:report.initcodeBytes},null,2));
